import pandas as pd
def clean(df):
    df = df.copy()
    # strip whitespace from text columns (fixes ' East' -> 'East')
    for col in ['Category', 'Region', 'Date']:
        if col in df.columns:
            df[col] = df[col].apply(lambda x: x.strip() if isinstance(x, str) else x)
    # fix Category misspellings
    cat_map = {'Office Suplies': 'Office Supplies', 'Accesories': 'Accessories'}
    if 'Category' in df.columns:
        df['Category'] = df['Category'].replace(cat_map)
    # ensure numeric types for Price/Quantity
    if 'Price' in df.columns:
        df['Price'] = pd.to_numeric(df['Price'], errors='coerce')
    if 'Quantity' in df.columns:
        df['Quantity'] = pd.to_numeric(df['Quantity'], errors='coerce')
    # drop exact duplicate rows (Order_ID 2004 duplicate)
    df = df.drop_duplicates()
    # enforce Order_ID uniqueness
    if 'Order_ID' in df.columns:
        df = df.drop_duplicates(subset=['Order_ID'], keep='first')
    # Date invalid dates not needed for this question, but coerce for completeness
    # df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    return df

def answer(df):
    # work on cleaned data (idempotent if already cleaned)
    # do not drop rows with missing Region - not needed for this question
    df = df.dropna(subset=['Category'])
    # drop rows where Price is missing after coercion
    df = df.dropna(subset=['Price'])
    grouped = df.groupby('Category')['Price'].mean()
    return {str(k): float(v) for k, v in grouped.items()}
